import React, { useState, useContext } from "react";
import { NavLink, useNavigate, useLocation, Link } from "react-router-dom";
import { Menu, X, User, LogOut, LayoutDashboard, Sparkles } from "lucide-react";
import { AuthContext } from "../Context/AuthContext";
import logo from "../images/logo.png";
import EnrollmentModal from "./EnrollmentModal";

const Navbar = () => {
  const { isAuth, user, logoutUser } = useContext(AuthContext);
  const navigate = useNavigate();
  const location = useLocation();
  const [isOpen, setIsOpen] = useState(false);
  const [enrollModalOpen, setEnrollModalOpen] = useState(false);

  const links = [
    { to: "/", label: "Home" },
    { to: "/courses", label: "Courses & Classes" },
    { to: "/teachers", label: "Faculty" },
    { to: "/about", label: "About Us" },
  ];

  const getDashboardPath = () => {
    if (!user) return "/login";
    switch (user.role) {
      case "ADMIN":
      case "SUPER_ADMIN":
        return "/admin";
      case "TEACHER":
        return "/teacher";
      case "PARENT":
        return "/parent";
      case "STUDENT":
        return "/student";
      default:
        return "/";
    }
  };

  const handleLogout = () => {
    logoutUser();
    navigate("/");
    setIsOpen(false);
  };

  return (
    <>
      <header className="bg-[#d49539] h-[90px] max-h-[90px] relative z-40 shadow-md">
        <div className="max-w-7xl mx-auto px-4 md:px-8 lg:px-12 py-3 flex items-center justify-between h-full">
          {/* Logo */}
          <div
            className="w-[140px] md:w-[170px] cursor-pointer flex items-center gap-2"
            onClick={() => navigate("/")}
          >
            <img src={logo} alt="Success Mentor logo" className="h-[60px] object-contain" />
          </div>

          {/* Desktop Nav Links */}
          <nav className="hidden md:flex items-center gap-1 lg:gap-5">
            {links.map((link) => {
              const isActive = location.pathname === link.to;
              return (
                <NavLink
                  to={link.to}
                  key={link.to}
                  className="relative py-2 px-3 font-bold text-sm lg:text-base text-[#304b62] hover:opacity-85 transition-colors"
                >
                  {link.label}
                  {isActive && (
                    <span className="absolute bottom-[-10px] left-0 right-0 h-[4px] bg-[#304b62] rounded-t-md" />
                  )}
                </NavLink>
              );
            })}
          </nav>

          {/* Right Action / Auth Buttons */}
          <div className="hidden md:flex items-center gap-3">
            {isAuth ? (
              <div className="flex items-center gap-2">
                <Link
                  to={getDashboardPath()}
                  className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-4 py-2 rounded-xl text-xs md:text-sm flex items-center gap-2 shadow-sm transition-all"
                >
                  <LayoutDashboard size={16} />
                  <span>Dashboard ({user?.role})</span>
                </Link>

                <button
                  onClick={handleLogout}
                  title="Log Out"
                  className="p-2 bg-white/20 hover:bg-white/30 text-[#304b62] rounded-xl transition-colors"
                >
                  <LogOut size={18} />
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-3">
                <button
                  onClick={() => navigate("/login")}
                  className="bg-white/20 hover:bg-white/30 text-[#304b62] font-extrabold px-4 py-2 rounded-xl text-sm transition-colors"
                >
                  Log In
                </button>
                <button
                  onClick={() => setEnrollModalOpen(true)}
                  className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-5 py-2.5 rounded-xl transition-colors shadow-md text-sm flex items-center gap-1.5"
                >
                  <Sparkles size={15} /> Admission Now
                </button>
              </div>
            )}
          </div>

          {/* Mobile Hamburger Button */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="md:hidden p-2 text-[#304b62] hover:bg-black/10 rounded-lg focus:outline-none"
            aria-label="Toggle Navigation Menu"
          >
            {isOpen ? <X size={26} /> : <Menu size={26} />}
          </button>
        </div>

        {/* Mobile Drawer */}
        {isOpen && (
          <div className="fixed inset-0 z-50 md:hidden flex justify-end">
            <div className="fixed inset-0 bg-black/50 transition-opacity" onClick={() => setIsOpen(false)} />
            <div className="relative w-72 bg-[#d49539] h-full p-6 shadow-2xl flex flex-col z-10 space-y-4">
              <div className="flex justify-between items-center pb-3 border-b border-[#304b62]/20">
                <span className="font-bold text-xl text-[#304b62]">Menu</span>
                <button onClick={() => setIsOpen(false)} className="p-1 text-[#304b62]">
                  <X size={24} />
                </button>
              </div>

              <div className="flex flex-col gap-2">
                {links.map((link) => (
                  <NavLink
                    to={link.to}
                    key={link.to}
                    onClick={() => setIsOpen(false)}
                    className="font-bold text-base py-2 px-3 rounded-lg text-[#304b62] hover:bg-black/10"
                  >
                    {link.label}
                  </NavLink>
                ))}

                {isAuth ? (
                  <>
                    <Link
                      to={getDashboardPath()}
                      onClick={() => setIsOpen(false)}
                      className="bg-[#304b62] text-white font-bold py-2.5 px-4 rounded-xl text-center text-sm mt-3"
                    >
                      Open Dashboard ({user?.role})
                    </Link>
                    <button
                      onClick={handleLogout}
                      className="bg-white/20 text-[#304b62] font-bold py-2 px-4 rounded-xl text-center text-sm"
                    >
                      Log Out
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      onClick={() => {
                        navigate("/login");
                        setIsOpen(false);
                      }}
                      className="w-full mt-3 bg-white/20 text-[#304b62] font-bold py-2.5 rounded-xl text-sm"
                    >
                      Log In
                    </button>
                    <button
                      onClick={() => {
                        setEnrollModalOpen(true);
                        setIsOpen(false);
                      }}
                      className="w-full bg-[#304b62] text-white font-bold py-2.5 rounded-xl text-sm"
                    >
                      Admission Now
                    </button>
                  </>
                )}
              </div>
            </div>
          </div>
        )}
      </header>

      {/* Global Enrollment Modal from Navbar */}
      <EnrollmentModal
        isOpen={enrollModalOpen}
        onClose={() => setEnrollModalOpen(false)}
        preselectedClass={10}
        preselectedCourse="General Admission Inquiry"
      />
    </>
  );
};

export default Navbar;
